                .table()
                .tensor()
                .is_same_node(model.tied_embedding().tensor())
        );
        assert_ne!(&*model.tied_embedding().tensor().value(), &embedding_before);
        assert_eq!(
            &*model.embedding().table().tensor().value(),
            &*model.parameters()[0].tensor().value()
        );
